const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
const amount=n=>Number.isSafeInteger(n)?(n/100).toLocaleString('da-DK',{minimumFractionDigits:2,maximumFractionDigits:2}):'Mangler';
export function invoiceBasisEditor(seed,api,url,onGenerated=()=>{}){
 const d=structuredClone(seed),dialog=el('dialog',null,'invoice-sheet-dialog'),bar=el('header'),close=el('button','Luk'),download=el('button','Download PDF','primary'),status=el('div',null,'invoice-sheet-status'),stage=el('div',null,'invoice-sheet-stage'),sheet=el('section',null,'invoice-sheet'),fields=[],lock=el('fieldset',null,'invoice-sheet-lock');
 d.requestId=crypto.randomUUID();let record,downloadURL;
 dialog.setAttribute('aria-label','Fakturagrundlag · redigér dokument');status.setAttribute('role','status');close.type=download.type='button';bar.append(el('strong','Fakturagrundlag'),el('span','Rettelser gælder kun denne PDF og ændrer ikke ordren. Ret ordrens fakturaoplysninger under Dokumenter → Fakturering, betaling og afstemning.'),download,close);dialog.append(bar,status,stage);stage.append(lock);lock.append(sheet);
 const cleanup=()=>{if(downloadURL)URL.revokeObjectURL(downloadURL);dialog.remove();};dialog.addEventListener('close',cleanup,{once:true});dialog.addEventListener('cancel',event=>{if(download.disabled)event.preventDefault();});close.onclick=()=>dialog.close();
 const changed=()=>{d.requestId=crypto.randomUUID();record=null;if(downloadURL){URL.revokeObjectURL(downloadURL);downloadURL=null;}status.replaceChildren();recalculate();};
 function input(parent,label,obj,key,{multiline=false,money=false,number=false,required=false,cls=''}={}){const n=el(multiline?'textarea':'input',null,cls);n.setAttribute('aria-label',label);n.placeholder=required?label+' mangler':label+' (valgfrit)';n.value=money?(obj[key]===null||obj[key]===undefined?'':(obj[key]/100).toFixed(2)):obj[key]??'';n.required=required;if(multiline)n.rows=1;if(!multiline)n.type=money||number?'number':'text';if(money||number){n.min='0';n.step=money?'0.01':'1';}function fit(){if(multiline){n.style.height='auto';n.style.height=n.scrollHeight+'px';}}function mark(){n.setAttribute('aria-invalid',String(required&&!String(n.value).trim()));}mark();n.oninput=()=>{obj[key]=money?(n.value===''?null:Math.round(Number(n.value)*100)):number?(n.value===''?null:Number(n.value)):n.value;mark();changed();fit();};parent.append(n);fields.push(n);return n;}
 const brand=el('div',null,'invoice-sheet-brand'),logo=el('img');logo.src='/assets/smerch.svg';logo.alt='Smerch';brand.append(logo);sheet.append(brand);
 const heading=el('div',null,'invoice-sheet-heading'),customer=el('section',null,'invoice-sheet-customer'),meta=el('section',null,'invoice-sheet-meta');heading.append(customer,meta);sheet.append(heading);
 input(customer,'Kundenavn',d.customer,'name',{required:true,cls:'sheet-customer-name'});const address=input(customer,'Faktureringsadresse',d.customer,'address',{multiline:true,required:true});
 if(!d.customer.address&&d.deliveryAddress){const copy=el('button','Brug leveringsadressen');copy.type='button';copy.onclick=()=>{address.value=d.customer.address=d.deliveryAddress;address.setAttribute('aria-invalid','false');copy.remove();changed();};customer.append(copy);}
 for(const [key,title] of [['cvr','CVR'],['ean','EAN']]){const label=el('label',title);input(label,title,d.customer,key);customer.append(label);}input(customer,'Kundens e-mail',d.customer,'email');
 meta.append(el('h2','FAKTURAGRUNDLAG'),el('p','Ikke en faktura eller betalingsanmodning.'));const ref=el('dl');ref.append(el('dt','Ordre nr:'),el('dd',d.reference));meta.append(ref);const date=el('label','Ordredato');input(date,'Gyldig ordredato',d,'date',{required:true});meta.append(date);const reference=el('label','Kundereference');input(reference,'Kundereference',d.customer,'reference');meta.append(reference);
 const tableWrap=el('div',null,'invoice-sheet-table-wrap'),table=el('table'),thead=el('thead'),hr=el('tr');for(const label of ['Nr.','Produkt / variant','Antal','Stk. pris','Pris ekskl. moms'])hr.append(el('th',label));thead.append(hr);table.append(thead);const tbody=el('tbody'),units=[];table.append(tbody);tableWrap.append(table);sheet.append(tableWrap);
 for(const [i,line] of d.lines.entries()){const row=el('tr'),description=el('td'),qty=el('td'),unit=el('td'),net=el('td');row.append(el('td',String(i+1)),description,qty,unit,net);input(description,'Vare '+(i+1)+': beskrivelse',line,'description',{multiline:true,required:true,cls:'sheet-line-name'});input(description,'Variant / varenummer / tryk',line,'variant',{multiline:true});input(description,'Rabat (allerede indregnet)',line,'discount');input(qty,'Vare '+(i+1)+': antal',line,'quantity',{number:true,required:true});input(net,'Vare '+(i+1)+': linjetotal ekskl. moms',line,'net',{money:true,required:true});units.push(unit);tbody.append(row);}
 const totals=el('section',null,'invoice-sheet-totals'),subtotal=el('strong'),total=el('strong');
 for(const [label,node] of [['Fragt ekskl. moms',null],['Subtotal ekskl. moms',subtotal],['Moms',null],['Total DKK inkl. moms',total]]){const row=el('div');row.append(el('span',label));if(node)row.append(node);else input(row,label,d,label==='Moms'?'vat':'freight',{money:true,required:true});totals.append(row);}sheet.append(totals);
 const terms=el('section',null,'invoice-sheet-terms');if(d.paymentInstruction)terms.append(el('strong','Forudbetaling før varebestilling og produktionsstart'),el('p',d.paymentInstruction));terms.append(el('p','Betalingsstatus: '+d.paymentStatus));const termsLabel=el('label','Betalingsbetingelser');const paymentTermsInput=input(termsLabel,'Betalingsbetingelser',d,'paymentTerms',{multiline:true,required:true});paymentTermsInput.readOnly=d.paymentProvider==='bank_transfer';terms.append(termsLabel);const notesLabel=el('label','Bemærkninger til bogholderen');input(notesLabel,'Bemærkninger til bogholderen',d,'notes',{multiline:true});terms.append(notesLabel,el('p','Den endelige faktura og fakturanummer oprettes manuelt i e-conomic.','sheet-disclaimer'));sheet.append(terms);
 const sender=el('footer',null,'invoice-sheet-sender');sender.append(el('strong','Smerch'));const senderGrid=el('div');for(const [key,label] of Object.entries({legalName:'Afsender: virksomhedsnavn',address:'Afsender: adresse',cvr:'Afsender: CVR',email:'Afsender: e-mail',phone:'Afsender: telefon'}))input(senderGrid,label,d.company,key,{multiline:key==='address',required:true});sender.append(senderGrid,el('small','Afsenderrettelser her gælder kun dette dokument.'));sheet.append(sender);
 function recalculate(){let net=d.freight??0;for(const [i,line] of d.lines.entries()){net+=line.net??0;units[i].textContent=line.quantity>0&&Number.isSafeInteger(line.net)?(line.net/100/line.quantity).toLocaleString('da-DK',{minimumFractionDigits:2,maximumFractionDigits:4}):'—';}subtotal.textContent=amount(net);total.textContent=amount(net+(d.vat??0));}recalculate();
 download.onclick=async()=>{let invalid;download.disabled=true;lock.disabled=true;close.disabled=true;status.textContent='Kontrollerer dokumentet…';try{const checked=await(await api(url,'POST',{action:'review',document:d})).json();if(checked.missing.length){status.replaceChildren(el('strong','Udfyld før download: '+checked.missing.join(', ')));invalid=fields.find(n=>n.getAttribute('aria-invalid')==='true');return;}if(!record){record=await(await api(url,'POST',{action:'generate',document:d})).json();if(record.pending){const link=el('a','Åbn dokumentstatus');link.href=record.workspace;status.replaceChildren(link);return;}onGenerated(record);}const blob=await(await api(url+'/'+record.id)).blob();if(downloadURL)URL.revokeObjectURL(downloadURL);downloadURL=URL.createObjectURL(blob);const a=el('a','Download PDF igen');a.href=downloadURL;a.download='Smerch-fakturagrundlag-'+d.reference.replace(/[^a-zA-Z0-9-]/g,'_')+'.pdf';status.replaceChildren(el('span','PDF’en er gemt som version '+record.version+'. '),a);a.click();}catch(error){status.textContent=error.message;}finally{download.disabled=false;lock.disabled=false;close.disabled=false;invalid?.focus();}};
 document.body.append(dialog);dialog.showModal();for(const n of fields)if(n.tagName==='TEXTAREA'){n.style.height='auto';n.style.height=n.scrollHeight+'px';}return {dialog,document:d};
}
